import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Is Clash compatible with Stash?","description":"How to move Stash Clash YAML, subscriptions, nodes, overrides, scripts and rules to Clash for iOS.","frontmatter":{"title":"Is Clash compatible with Stash?","description":"How to move Stash Clash YAML, subscriptions, nodes, overrides, scripts and rules to Clash for iOS.","head":[["meta",{"name":"keywords","content":"Stash to Clash,Stash subscription,Stash config,Stash YAML,Clash iOS,mihomo iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Can a Stash configuration be used in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Standard Clash or mihomo YAML can be imported directly. Recreate Stash overrides, HTTP engine, MITM, rewrites, scripts and device settings with matching Clash features.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I use a Stash subscription in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes when the subscription returns standard Clash or mihomo YAML. Add the same URL to Clash and change the subscription User-Agent when necessary.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/stash.md","filePath":"guide/compatibility/stash.md","lastUpdated":1785318168000}`),a={name:`guide/compatibility/stash.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="is-clash-compatible-with-stash" tabindex="-1">Is Clash compatible with Stash? <a class="header-anchor" href="#is-clash-compatible-with-stash" aria-label="Permalink to “Is Clash compatible with Stash?”">​</a></h1><p><strong>Standard Clash / mihomo YAML and subscriptions can be used directly.</strong></p><p>The Stash documentation says it imports <a href="https://stash.wiki/en/get-started" target="_blank" rel="noreferrer">Stash / Clash formatted configurations</a>, and that <a href="https://stash.wiki/en/configuration/example-config" target="_blank" rel="noreferrer">its configuration files use YAML</a>. A standard Clash or mihomo YAML configuration used in Stash can therefore be imported directly into Clash.</p><h2 id="what-moves-directly" tabindex="-1">What moves directly? <a class="header-anchor" href="#what-moves-directly" aria-label="Permalink to “What moves directly?”">​</a></h2><ul><li>standard Clash / mihomo YAML configurations;</li><li>remote subscriptions returning Clash / mihomo YAML;</li><li>nodes, proxy providers and rule providers;</li><li>policy groups, health checks and routing rules;</li><li>DNS and other fields supported by both apps.</li></ul><h2 id="fastest-migration-path" tabindex="-1">Fastest migration path <a class="header-anchor" href="#fastest-migration-path" aria-label="Permalink to “Fastest migration path”">​</a></h2><ol><li>Copy the subscription URL used by the active Stash configuration.</li><li>Add it as a remote configuration in Clash.</li><li>A local YAML file can also be opened or shared into Clash.</li><li>Update the profile and check its nodes, groups and rules.</li><li>When the provider offers multiple formats, change the subscription User-Agent and select Clash / mihomo output.</li></ol><h2 id="recreate-stash-features-in-clash" tabindex="-1">Recreate Stash features in Clash <a class="header-anchor" href="#recreate-stash-features-in-clash" aria-label="Permalink to “Recreate Stash features in Clash”">​</a></h2><ul><li>consolidate override files into a clear mihomo YAML configuration;</li><li>recreate HTTP engine, MITM and certificate needs with matching features;</li><li>express URL rewrite and script needs with Clash rules and matching features;</li><li>set on-demand behavior, sync, remote control and app preferences to match your workflow.</li></ul><p>If Stash combines multiple override files dynamically, export or consolidate the result as standard mihomo YAML, then map Stash extension needs to the corresponding Clash features.</p><h2 id="can-i-keep-using-the-same-server" tabindex="-1">Can I keep using the same server? <a class="header-anchor" href="#can-i-keep-using-the-same-server" aria-label="Permalink to “Can I keep using the same server?”">​</a></h2><p>The same server can be used directly when both apps use the same standard node configuration.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>.</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};